          twentyCLIAccessToken: credentials.accessToken,
          twentyCLIRegistrationClientId: credentials.clientId,
          ...(isDefined(credentials.refreshToken)
            ? { twentyCLIRefreshToken: credentials.refreshToken }
            : {}),
        }),
  };
};

